import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import type { Plugin, PreviewServer, ViteDevServer } from 'vite'

/**
 * The locally-issued development certificate, and a route that hands the CA to
 * a phone.
 *
 * Generated by `npm run cert` / `npm run cert` (see scripts/dev-cert.mjs). When it
 * is absent the dev server falls back to `@vitejs/plugin-basic-ssl`, which is
 * fine for desktop work but cannot install as a PWA on a phone — its
 * certificate does not cover the LAN address, and a browser will not register a
 * service worker on an origin with a certificate error.
 */

/** How to spell "run a script" for whoever started the dev server. */
const RUN = (process.env.npm_config_user_agent ?? '').startsWith('npm/')
  ? 'npm run'
  : 'npm run'

const CERT_DIR = resolve(process.cwd(), 'certs')
const CA_CRT = resolve(CERT_DIR, 'dev-ca.crt')
const SERVER_KEY = resolve(CERT_DIR, 'dev-server.key')
const SERVER_CRT = resolve(CERT_DIR, 'dev-server.crt')

/** The key/cert pair for Vite's `server.https`, or null when none was generated. */
export function localCert(): { key: Buffer; cert: Buffer } | null {
  if (!existsSync(SERVER_KEY) || !existsSync(SERVER_CRT)) return null
  return { key: readFileSync(SERVER_KEY), cert: readFileSync(SERVER_CRT) }
}

/**
 * Serves the CA at `/dev-ca.crt` so a phone can install it by visiting the URL.
 *
 * The `application/x-x509-ca-cert` content type is what makes Android and iOS
 * treat the response as a certificate to install rather than a file to
 * download. No `Content-Disposition`: on iOS an attachment disposition sends it
 * to Files instead of offering it as a configuration profile.
 */
export function devCa(): Plugin {
  const middleware = (
    req: { url?: string },
    res: {
      statusCode: number
      setHeader: (name: string, value: string) => void
      end: (body?: string | Buffer) => void
    },
    next: () => void,
  ) => {
    const path = (req.url ?? '').split('?')[0]
    if (path !== '/dev-ca.crt') return next()

    if (!existsSync(CA_CRT)) {
      res.statusCode = 404
      res.setHeader('Content-Type', 'text/plain; charset=utf-8')
      res.end(`No development CA has been generated. Run: ${RUN} cert`)
      return
    }

    res.setHeader('Content-Type', 'application/x-x509-ca-cert')
    res.end(readFileSync(CA_CRT))
  }

  return {
    name: 'protocol-scanner:dev-ca',
    configureServer(server: ViteDevServer) {
      server.middlewares.use(middleware)
    },
    configurePreviewServer(server: PreviewServer) {
      server.middlewares.use(middleware)
    },
  }
}
